// Manual p.55 supplies the catalog and qualitative effects; numeric tuning is approximate.
export const RECREATION={largePark:{name:'Large park',size:3,cost:600,upkeep:6,radius:8,amenity:16,green:12,health:2,sprite:45},fountain:{name:'Fountain',size:1,cost:100,upkeep:1,radius:4,amenity:12,green:0,health:0,sprite:46},pond:{name:'Ornamental pond',size:1,cost:100,upkeep:1,radius:4,amenity:10,green:3,health:1,sprite:47},playground:{name:'Playground',size:2,cost:300,upkeep:3,radius:5,amenity:12,green:2,health:3,sprite:48},marina:{name:'Marina',size:3,cost:1000,upkeep:12,radius:8,amenity:18,green:0,health:2,sprite:49},zoo:{name:'Zoo',size:4,cost:3000,upkeep:30,radius:10,amenity:20,green:5,health:1,sprite:50},sportsPark:{name:'Sports park',size:3,cost:1000,upkeep:10,radius:7,amenity:14,green:3,health:5,sprite:51}};
export function recreationRoots(c){const n=Math.sqrt(c.tiles.length);return c.tiles.filter(t=>RECREATION[t.type]&&t.root===t.y*n+t.x);}
export function recreationActive(c,t){return !c.tiles.some(u=>u.root===t.root&&(u.fire||u.radiation||u.rubble));}
export function recreationStats(c){const roots=recreationRoots(c);return{recreationCount:roots.length,recreationUpkeep:roots.reduce((v,t)=>v+RECREATION[t.type].upkeep,0),activeZoos:roots.filter(t=>t.type==='zoo'&&recreationActive(c,t)).length};}
